/**
 * Browser evaluator: a line-for-line port of src/backend/deaths_warrant/evaluate.py.
 * Every model's golden.json (generated by the Python reference) is replayed against this
 * file in evaluate.test.ts, so the two cannot silently drift. Change both together.
 */

import { RecordError } from "../errors";
import { layerInputs, termInputs, type Band, type Input, type ModelSpec, type RelativeSurvivalCurve, type ScoreSurvival, type Survival, type Term, type Value, type WeightedValue } from "./spec";

export const HORIZON_YEARS = 60;
const BISECTION_STEPS = 64;
const CURVE_STEP_YEARS = 0.25;
const CURVE_END_YEARS = 30;
const SURVIVAL_TIMES = [1, 3, 5] as const;

export type Observed = Record<string, Value | null | undefined>;
type SurvivalFn = (t: number) => number;
export type InputStatus = "observed" | "missing" | "implausible" | "unused";

/** A required input (such as the birth date) is missing: a problem with the record, not a bug. */
export class EvaluationError extends RecordError {}

export interface EvaluationResult {
  model: string;
  model_version: string;
  layer: { id: string; label: string };
  skipped_layers: { id: string; label: string; lacking: string[] }[];
  median_years: number | null;
  range_low_years: number | null;
  range_high_years: number | null;
  survival_at: Record<string, number>;
  beyond_reliable: boolean;
  curve: [number, number][];
  inputs: { id: string; label: string; status: InputStatus; value: Value | null; assumed: WeightedValue[] | null }[];
  terms: { input: string; kind: Term["kind"]; contribution: number | null }[];
}

/** Mirrors Input.accepts in spec.py: change both together. */
function plausible(i: Input, v: Value): boolean {
  if (i.type === "number") return typeof v === "number" && Number.isFinite(v) && i.min <= v && v <= i.max;
  if (i.type === "enum") return typeof v === "string" && i.values.includes(v);
  return typeof v === "boolean";
}

export function resolveInputs(spec: ModelSpec, observed: Observed) {
  const values: Record<string, Value> = {};
  const status: Record<string, InputStatus> = {};
  for (const i of spec.inputs) {
    const v = observed[i.id];
    if (v === null || v === undefined) status[i.id] = "missing";
    else if (plausible(i, v)) {
      values[i.id] = v;
      status[i.id] = "observed";
    } else status[i.id] = "implausible";
    if (!(i.id in values) && i.missing === null) {
      throw new EvaluationError(`${i.label} is required but was not found in the record`);
    }
  }
  return { values, status };
}

function band<T extends { lt: number | null }>(bands: T[], x: number): T {
  for (const b of bands) if (b.lt === null || x < b.lt) return b;
  throw new Error("unreachable: the last band is a catch-all");
}

export function termValue(term: Term, values: Record<string, Value>): number {
  const x = values[term.input]!;
  switch (term.kind) {
    case "grid":
      return band<Band>(band(term.rows, Number(x)).bands, Number(values[term.by])).value;
    case "linear": {
      let xf = Number(x);
      if (term.min !== null) xf = Math.max(xf, term.min);
      if (term.max !== null) xf = Math.min(xf, term.max);
      return term.coef * (xf - term.center);
    }
    case "bands":
      return band(term.bands, Number(x)).value;
    case "category": {
      const key = typeof x === "boolean" ? (x ? "true" : "false") : String(x);
      return term.values[key]!;
    }
  }
}

export function populationCumHazard(table: number[], age: number, t: number): number {
  const end = age + t;
  let total = 0;
  let x = age;
  while (x < end) {
    const i = Math.floor(x);
    const next = Math.min(i + 1, end);
    const q = table[Math.min(i, table.length - 1)]!;
    total += -Math.log1p(-q) * (next - x);
    x = next;
  }
  return total;
}

/** Excess cumulative hazard -ln R(k) at whole years k = 0..n. */
export function excessKnots(relative: number[]): number[] {
  return [0, ...relative.map((r) => -Math.log(r))];
}

/** Linear between whole years. Beyond the last year, the last year's slope continues. */
export function excessCumHazard(knots: number[], t: number): number {
  const n = knots.length - 1;
  if (t >= n) return knots[n]! + (knots[n]! - knots[n - 1]!) * (t - n);
  const k = Math.floor(t);
  return knots[k]! + (knots[k + 1]! - knots[k]!) * (t - k);
}

/** First curve matching the keys and the age at diagnosis (age - years since diagnosis). */
export function selectCurve(survival: Extract<Survival, { type: "relative_survival" }>, values: Record<string, Value>): RelativeSurvivalCurve {
  const ageAtDiagnosis = Number(values[survival.age_input]) - Number(values[survival.since_input]);
  const curve = survival.curves.find(
    (c) => Object.entries(c.match).every(([k, v]) => values[k] === v) && (c.age_lt === null || ageAtDiagnosis < c.age_lt),
  );
  if (!curve) throw new Error("unreachable: the spec guarantees an all-ages curve");
  return curve;
}

/** Integer risk score: the rounded term sum, clamped to the published table. */
export function scoreOf(survival: ScoreSurvival, values: Record<string, Value>): number {
  let total = 0;
  for (const term of survival.terms) total += termValue(term, values);
  return Math.min(Math.max(pyRound(total), 0), survival.survival.length - 1);
}

/** Python's round(): halves go to the even neighbour (Math.round sends them up). */
function pyRound(x: number): number {
  const r = Math.round(x);
  return Math.abs(x % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
}

const sexTable = (spec: ModelSpec, name: string, sex: Value) =>
  sex === "female" ? spec.life_tables[name]!.female : spec.life_tables[name]!.male;

/**
 * The survival function for one set of input values, plus a key: combinations with equal keys
 * have identical functions, so a mixture can merge them (null = never merged).
 */
function survivalFn(spec: ModelSpec, layerIndex: number, values: Record<string, Value>): [string | null, SurvivalFn] {
  const survival = spec.layers[layerIndex]!.survival;
  if (survival.type === "score_weibull") return scoreWeibullFn(spec, survival, values);
  if (survival.type === "score_life_table") return scoreLifeTableFn(spec, survival, values);
  let lp = 0;
  for (const term of survival.terms) lp += termValue(term, values);
  const hr = Math.exp(lp);
  if (survival.type === "weibull_ph") {
    const { shape, scale_years: scale } = survival;
    return [null, (t) => Math.exp(-hr * (t / scale) ** shape)];
  }
  const q = sexTable(spec, survival.life_table, values[survival.sex_input]!);
  const age = Number(values[survival.age_input]);
  if (survival.type === "life_table_ph") return [null, (t) => Math.exp(-hr * populationCumHazard(q, age, t))];
  const since = Number(values[survival.since_input]);
  const knots = excessKnots(selectCurve(survival, values).relative);
  const x0 = excessCumHazard(knots, since);
  return [null, (t) => Math.exp(-populationCumHazard(q, age, t) - hr * (excessCumHazard(knots, since + t) - x0))];
}

function scoreLifeTableFn(spec: ModelSpec, survival: Extract<Survival, { type: "score_life_table" }>, values: Record<string, Value>): [string, SurvivalFn] {
  const score = scoreOf(survival, values);
  const sex = values[survival.sex_input]!;
  const q = sexTable(spec, survival.life_table, sex);
  const age = Number(values[survival.age_input]);
  const hPop = populationCumHazard(q, age, survival.time);
  const hr = Math.max(1, -Math.log(survival.survival[score]!) / hPop);
  return [JSON.stringify([score, age, sex]), (t) => Math.exp(-hr * populationCumHazard(q, age, t))];
}

function scoreWeibullFn(spec: ModelSpec, survival: Extract<Survival, { type: "score_weibull" }>, values: Record<string, Value>): [string, SurvivalFn] {
  const score = scoreOf(survival, values);
  const [t1, t2] = survival.times;
  const [s1, s2] = survival.survival[score]!;
  const h1 = -Math.log(s1);
  const k = Math.log(Math.log(s2) / Math.log(s1)) / Math.log(t2 / t1);
  const weibull = (t: number) => Math.exp(-h1 * (t / t1) ** k);
  if (survival.life_table === null) return [JSON.stringify([score]), weibull];
  const sex = values[survival.sex_input]!;
  const q = sexTable(spec, survival.life_table, sex);
  const age = Number(values[survival.age_input]);
  return [JSON.stringify([score, age, sex]), (t) => Math.min(weibull(t), Math.exp(-populationCumHazard(q, age, t)))];
}

export function solveTime(s: SurvivalFn, p: number): number | null {
  if (s(HORIZON_YEARS) > p) return null;
  let lo = 0;
  let hi = HORIZON_YEARS;
  for (let k = 0; k < BISECTION_STEPS; k++) {
    const mid = (lo + hi) / 2;
    if (s(mid) > p) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

/** Cartesian product in itertools.product order (last list varies fastest). */
function product<T>(lists: T[][]): T[][] {
  let out: T[][] = [[]];
  for (const list of lists) out = out.flatMap((prefix) => list.map((item) => [...prefix, item]));
  return out;
}

export function evaluate(spec: ModelSpec, observed: Observed): EvaluationResult {
  const resolved = resolveInputs(spec, observed);
  const skipped: EvaluationResult["skipped_layers"] = [];
  let layerIndex = 0;
  for (; layerIndex < spec.layers.length; layerIndex++) {
    const layer = spec.layers[layerIndex]!;
    const lacking = layer.requires.filter((r) => !(r in resolved.values));
    for (const [n, allowed] of Object.entries(layer.when)) if (!allowed.includes(resolved.values[n] as Value)) lacking.push(n);
    if (!lacking.length) break;
    skipped.push({ id: layer.id, label: layer.label, lacking });
  }
  const layer = spec.layers[layerIndex]!;
  const inputs = new Map(spec.inputs.map((i) => [i.id, i]));
  const used = layerInputs(layer);
  const unknown = used.filter((n) => !(n in resolved.values));

  const fns: SurvivalFn[] = [];
  const weights: number[] = [];
  const slots = new Map<string, number>();
  for (const combo of product(unknown.map((n) => inputs.get(n)!.missing ?? []))) {
    const values = { ...resolved.values };
    let weight = 1;
    combo.forEach((wv, k) => {
      values[unknown[k]!] = wv.value;
      weight *= wv.weight;
    });
    const [key, fn] = survivalFn(spec, layerIndex, values);
    const slot = key === null ? undefined : slots.get(key);
    if (slot !== undefined) {
      weights[slot]! += weight;
      continue;
    }
    if (key !== null) slots.set(key, fns.length);
    fns.push(fn);
    weights.push(weight);
  }
  let totalWeight = 0;
  for (const w of weights) totalWeight += w;

  const s: SurvivalFn = (t) => {
    let acc = 0;
    for (let k = 0; k < fns.length; k++) acc += weights[k]! * fns[k]!(t);
    return acc / totalWeight;
  };

  const median = solveTime(s, 0.5);
  const steps = Math.round(CURVE_END_YEARS / CURVE_STEP_YEARS);
  return {
    model: spec.id,
    model_version: spec.version,
    layer: { id: layer.id, label: layer.label },
    skipped_layers: skipped,
    median_years: median,
    range_low_years: solveTime(s, 0.75),
    range_high_years: solveTime(s, 0.25),
    survival_at: Object.fromEntries(SURVIVAL_TIMES.map((t) => [String(t), s(t)])),
    beyond_reliable: median === null || median > spec.max_reliable_years,
    curve: Array.from({ length: steps + 1 }, (_, k) => [k * CURVE_STEP_YEARS, s(k * CURVE_STEP_YEARS)]),
    inputs: spec.inputs.map((i) => ({
      id: i.id,
      label: i.label,
      status: used.includes(i.id) ? resolved.status[i.id]! : "unused",
      value: resolved.values[i.id] ?? null,
      assumed: unknown.includes(i.id) ? (i.missing ?? []) : null,
    })),
    terms: layer.survival.terms.map((t) => ({
      input: t.input,
      kind: t.kind,
      contribution: termInputs(t).every((n) => n in resolved.values) ? termValue(t, resolved.values) : null,
    })),
  };
}
